import itertools, random, time
from test_reduce import solve_one_in_three_sat, solve_exact_cover
from reduce import reduce

# Count yes/no in the exhaustive m<=5 set
yes=no=0
for m in range(0,6):
    triples=list(itertools.combinations(range(1,m+1),3))
    for r in range(len(triples)+1):
        for combo in itertools.combinations(triples,r):
            inst={"num_vars":m,"clauses":[list(t) for t in combo]}
            if solve_one_in_three_sat(inst): yes+=1
            else: no+=1
print("exhaustive m<=5: yes=",yes,"no=",no)

# Find a small unsatisfiable positive 1-in-3-SAT instance
found=None
for m in range(3,7):
    triples=list(itertools.combinations(range(1,m+1),3))
    for r in range(len(triples)+1):
        for combo in itertools.combinations(triples,r):
            inst={"num_vars":m,"clauses":[list(t) for t in combo]}
            if not solve_one_in_three_sat(inst):
                found=inst; break
        if found: break
    if found: break
print("first unsat found:", found)
red=reduce(found)
print("reduced:", red, "target ans:", solve_exact_cover(red))

# Performance / polynomial check on a larger instance
rng=random.Random(7)
m=200; clauses=[rng.sample(range(1,m+1),3) for _ in range(500)]
inst={"num_vars":m,"clauses":clauses}
t=time.time(); red=reduce(inst); dt=time.time()-t
print("large reduce time:", round(dt,4),"s; universe_size:", red["universe_size"], "num sets:", len(red["sets"]))
EOF"}

